import json
from itertools import permutations

def solve_puzzle():
    # Input variables (attributes and their possible values)
    houses = [1, 2, 3]
    names = ["Peter", "Eric", "Arnold"]
    educations = ["bachelor", "associate", "high school"]
    occupations = ["teacher", "doctor", "engineer"]

    solutions = []

    # Helper lambdas
    def invert(d):
        return {v: k for k, v in d.items()}

    for name_perm in permutations(names):
        house_to_name = {houses[i]: name_perm[i] for i in range(3)}
        name_to_house = invert(house_to_name)

        for edu_perm in permutations(educations):
            house_to_edu = {houses[i]: edu_perm[i] for i in range(3)}
            edu_to_house = invert(house_to_edu)

            # Clue 3: Peter is the person with a high school diploma.
            if name_to_house["Peter"] != edu_to_house["high school"]:
                continue

            # Clue 2: The person with an associate's degree and Eric are next to each other.
            if abs(edu_to_house["associate"] - name_to_house["Eric"]) != 1:
                continue

            for occ_perm in permutations(occupations):
                house_to_occ = {houses[i]: occ_perm[i] for i in range(3)}
                occ_to_house = invert(house_to_occ)

                # Clue 1: The teacher is directly left of the person with an associate's degree.
                if occ_to_house["teacher"] != edu_to_house["associate"] - 1:
                    continue

                # Clue 4: The doctor is the person with a bachelor's degree.
                if occ_to_house["doctor"] != edu_to_house["bachelor"]:
                    continue

                solutions.append((house_to_name, house_to_edu, house_to_occ))

    return solutions

def format_solution(solution):
    house_to_name, house_to_edu, house_to_occ = solution
    header = ["House", "Name", "level of education", "occupation"]
    rows = []
    for h in [1, 2, 3]:
        rows.append([str(h), house_to_name[h], house_to_edu[h], house_to_occ[h]])
    return {"solution": {"header": header, "rows": rows}}

def main():
    solutions = solve_puzzle()
    if not solutions:
        print(json.dumps({"error": "No solution found"}))
        return
    # Assuming unique solution; choose the first
    output = format_solution(solutions[0])
    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    main()
